import heapq

def match(orders):
    book = {}  # id -> dict(side, price, qty, arrival, active)
    buy_heap = []   # entries: (-price, arrival, id)
    sell_heap = []  # entries: (price, arrival, id)
    trades = []

    def push_buy(oid):
        o = book[oid]
        heapq.heappush(buy_heap, (-o['price'], o['arrival'], oid))

    def push_sell(oid):
        o = book[oid]
        heapq.heappush(sell_heap, (o['price'], o['arrival'], oid))

    def top_valid(heap):
        while heap:
            entry = heap[0]
            oid = entry[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return oid
        return None

    for idx, order in enumerate(orders):
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        book[oid] = {'side': side, 'price': price, 'qty': qty, 'arrival': idx, 'active': True}

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while book[oid]['qty'] > 0:
            opp_id = top_valid(opp_heap)
            if opp_id is None:
                break
            opp = book[opp_id]

            if typ != 'market':
                if side == 'buy' and opp['price'] > price:
                    break
                if side == 'sell' and opp['price'] < price:
                    break

            trade_qty = min(book[oid]['qty'], opp['qty'])
            trade_price = opp['price']

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            book[oid]['qty'] -= trade_qty
            opp['qty'] -= trade_qty

            if opp['qty'] <= 0:
                opp['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and book[oid]['qty'] > 0:
            if side == 'buy':
                push_buy(oid)
            else:
                push_sell(oid)
        else:
            # ioc/market leftover discarded, or limit fully filled
            if book[oid]['qty'] > 0:
                book[oid]['active'] = False

    return trades

